INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c4fd828b-d31e-5736-b97f-f6baff242943', 'Netherlands Laws of Environmental Conservation', 'Laws of Environmental Conservation', 'The 2012 revision of the Dutch Environmental Management Act (Wet milieubeheer) establishes a comprehensive legal framework for environmental protection and sustainable development in the Netherlands. The law addresses various domains, including waste management, air quality, water pollution, and energy efficiency, with the overarching goal of mitigating environmental harm and fostering a circular economy. Key provisions include the establishment of waste management hierarchies, emission reduction targets, and guidelines for energy conservation.

The act mandates businesses to adopt measures that minimize waste, reduce pollution, and enhance resource efficiency. Specific requirements apply to industries such as manufacturing, utilities, and transportation, focusing on minimizing their environmental footprints. Local and provincial authorities are empowered to enforce compliance through permitting systems, inspections, and penalties.

Aligned with EU directives such as the Waste Framework Directive and the Water Framework Directive, the act ensures that Dutch regulations are consistent with European standards. It also emphasizes public involvement in environmental decision-making, requiring transparency and stakeholder engagement in the approval of major projects.', 'The 2012 revision of the Dutch Environmental Management Act (Wet milieubeheer) establishes a comprehensive legal framework for environmental protection and sustainable development in the Netherlands. The law addresses various domains, including waste management, air quality, water pollution, and energy efficiency, with the overarching goal of mitigating environmental harm and fostering a circular economy. Key provisions include the establishment of waste management hierarchies, emission reduction targets, and guidelines for energy conservation.

The act mandates businesses to adopt measures that minimize waste, reduce pollution, and enhance resource efficiency. Specific requirements apply to industries such as manufacturing, utilities, and transportation, focusing on minimizing their environmental footprints. Local and provincial authorities are empowered to enforce compliance through permitting systems, inspections, and penalties.

Aligned with EU directives such as the Waste Framework Directive and the Water Framework Directive, the act ensures that Dutch regulations are consistent with European standards. It also emphasizes public involvement in environmental decision-making, requiring transparency and stakeholder engagement in the approval of major projects.', 'The 2012 revision of the Dutch Environmental Management Act (Wet milieubeheer) establishes a comprehensive legal framework for environmental protection and sustainable development in the Netherlands. The law addresses various domains, including waste management, air quality, water pollution, and energy efficiency, with the overarching goal of mitigating environmental harm and fostering a circular economy. Key provisions include the establishment of waste management hierarchies, emission reduction targets, and guidelines for energy conservation.

The act mandates businesses to adopt measures that minimize waste, reduce pollution, and enhance resource efficiency. Specific requirements apply to industries such as manufacturing, utilities, and transportation, focusing on minimizing their environmental footprints. Local and provincial authorities are empowered to enforce compliance through permitting systems, inspections, and penalties.

Aligned with EU directives such as the Waste Framework Directive and the Water Framework Directive, the act ensures that Dutch regulations are consistent with European standards. It also emphasizes public involvement in environmental decision-making, requiring transparency and stakeholder engagement in the approval of major projects.', 'Netherlands', 'climate', 'in_force', '2012-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_5', ARRAY['sdg13', 'other sustainability policy', 'netherlands', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'sdg16', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1989f2ec-39f8-5e19-9c3a-7e095bc5f8d0', 'Netherlands Best Practices for Engaged Share-Ownership inteded for Eumedion', 'Best Practices for Engaged Share-Ownership inteded for Eumedion Participants Adopted on 30 June 2011', 'Eumedion has drafted this series of best practices as guidance for its participants – which include pension funds and the asset managers of these pension funds – in fulfilling their essential role in the governance of listed companies.', 'Eumedion has drafted this series of best practices as guidance for its participants – which include pension funds and the asset managers of these pension funds – in fulfilling their essential role in the governance of listed companies.', 'Eumedion has drafted this series of best practices as guidance for its participants – which include pension funds and the asset managers of these pension funds – in fulfilling their essential role in the governance of listed companies.', 'Netherlands', 'governance', 'in_force', '2011-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_11', ARRAY['other sustainability policy', 'netherlands', 'regulations', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('166cfcd4-21b7-5203-bd89-df2f3cae43a6', 'Netherlands Insurer Governance Principles', 'Insurer Governance Principles, 2010', 'These Governance Principles, referred to as ‘the Code’, were drafted by the ‘Dutch Association of Insurers’ (Verbond van Verzekeraars, also referred to as ‘the Association’), in addition to the ‘Code of Conduct for Insurers’ (Gedragscode Verzekeraars) drafted in 2002. The Code is consistent with the basic tenets of the Banking Code (Code Banken) drafted by the ‘Dutch Banking Association’ (Nederlandse Vereniging van Banken). The Code applies to all insurers that hold a licence granted under the ‘Financial Supervision Act’ (Wet op het financieel toezicht (Wft)).', 'These Governance Principles, referred to as ‘the Code’, were drafted by the ‘Dutch Association of Insurers’ (Verbond van Verzekeraars, also referred to as ‘the Association’), in addition to the ‘Code of Conduct for Insurers’ (Gedragscode Verzekeraars) drafted in 2002. The Code is consistent with the basic tenets of the Banking Code (Code Banken) drafted by the ‘Dutch Banking Association’ (Nederlandse Vereniging van Banken). The Code applies to all insurers that hold a licence granted under the ‘Financial Supervision Act’ (Wet op het financieel toezicht (Wft)).', 'These Governance Principles, referred to as ‘the Code’, were drafted by the ‘Dutch Association of Insurers’ (Verbond van Verzekeraars, also referred to as ‘the Association’), in addition to the ‘Code of Conduct for Insurers’ (Gedragscode Verzekeraars) drafted in 2002. The Code is consistent with the basic tenets of the Banking Code (Code Banken) drafted by the ‘Dutch Banking Association’ (Nederlandse Vereniging van Banken). The Code applies to all insurers that hold a licence granted under the ‘Financial Supervision Act’ (Wet op het financieel toezicht (Wft)).', 'Netherlands', 'nature', 'in_force', '2010-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_16', ARRAY['guidance_frameworks', 'other sustainability policy', 'netherlands', 'sdg16', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f4014f54-2d78-5c5c-aa6d-be271d9e2b3e', 'Netherlands Banking Code', 'Banking Code - 2009', 'This Banking Code (Code Banken) was drawn up by the Netherlands Bankers’ Association (NVB) in response to the report entitled ‘Restoring Trust’ (‘Naar herstel van vertrouwen’), which was published by the Advisory Committee on the Future of Banks (Adviescommissie Toekomst Banken) on 7 April 2009. The recommendations from chapters 1 and 2 of the Advisory Committee’s report have been used as the basis for this Banking Code.', 'This Banking Code (Code Banken) was drawn up by the Netherlands Bankers’ Association (NVB) in response to the report entitled ‘Restoring Trust’ (‘Naar herstel van vertrouwen’), which was published by the Advisory Committee on the Future of Banks (Adviescommissie Toekomst Banken) on 7 April 2009. The recommendations from chapters 1 and 2 of the Advisory Committee’s report have been used as the basis for this Banking Code.', 'This Banking Code (Code Banken) was drawn up by the Netherlands Bankers’ Association (NVB) in response to the report entitled ‘Restoring Trust’ (‘Naar herstel van vertrouwen’), which was published by the Advisory Committee on the Future of Banks (Adviescommissie Toekomst Banken) on 7 April 2009. The recommendations from chapters 1 and 2 of the Advisory Committee’s report have been used as the basis for this Banking Code.', 'Netherlands', 'climate', 'in_force', '2009-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_10', ARRAY['guidance_frameworks', 'other sustainability policy', 'netherlands', 'mandatory', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a211e139-d472-5228-b722-1b29fcd2cc3a', 'Netherlands Dutch Corporate Governance Code', 'The Dutch Corporate Governance Code', 'The Dutch Corporate Governance Code of 2008 sets out principles and best practice provisions for effective corporate governance among listed companies in the Netherlands. The code promotes transparency, accountability, and sustainable long-term value creation by outlining responsibilities for management boards, supervisory boards, shareholders, and auditors. It is built on two core pillars: integrity and transparency in decision-making, and proper supervision.

Key elements include the "comply or explain" principle, requiring companies to report on how they adhere to the code’s provisions or justify deviations. The code also establishes rules for remuneration policies, risk management, and conflict of interest resolutions. Specific provisions address the composition, roles, and responsibilities of management and supervisory boards, emphasizing diversity, independence, and financial expertise. Additionally, it requires annual disclosures on corporate governance structures and practices.

Aligned with EU directives, the code reflects international best practices, ensuring competitiveness and investor confidence in Dutch companies. It applies to all Dutch-listed companies and includes provisions for institutional investors to act transparently and responsibly. The code fosters a collaborative approach to corporate governance, enhancing trust among stakeholders.', 'The Dutch Corporate Governance Code of 2008 sets out principles and best practice provisions for effective corporate governance among listed companies in the Netherlands. The code promotes transparency, accountability, and sustainable long-term value creation by outlining responsibilities for management boards, supervisory boards, shareholders, and auditors. It is built on two core pillars: integrity and transparency in decision-making, and proper supervision.

Key elements include the "comply or explain" principle, requiring companies to report on how they adhere to the code’s provisions or justify deviations. The code also establishes rules for remuneration policies, risk management, and conflict of interest resolutions. Specific provisions address the composition, roles, and responsibilities of management and supervisory boards, emphasizing diversity, independence, and financial expertise. Additionally, it requires annual disclosures on corporate governance structures and practices.

Aligned with EU directives, the code reflects international best practices, ensuring competitiveness and investor confidence in Dutch companies. It applies to all Dutch-listed companies and includes provisions for institutional investors to act transparently and responsibly. The code fosters a collaborative approach to corporate governance, enhancing trust among stakeholders.', 'The Dutch Corporate Governance Code of 2008 sets out principles and best practice provisions for effective corporate governance among listed companies in the Netherlands. The code promotes transparency, accountability, and sustainable long-term value creation by outlining responsibilities for management boards, supervisory boards, shareholders, and auditors. It is built on two core pillars: integrity and transparency in decision-making, and proper supervision.

Key elements include the "comply or explain" principle, requiring companies to report on how they adhere to the code’s provisions or justify deviations. The code also establishes rules for remuneration policies, risk management, and conflict of interest resolutions. Specific provisions address the composition, roles, and responsibilities of management and supervisory boards, emphasizing diversity, independence, and financial expertise. Additionally, it requires annual disclosures on corporate governance structures and practices.

Aligned with EU directives, the code reflects international best practices, ensuring competitiveness and investor confidence in Dutch companies. It applies to all Dutch-listed companies and includes provisions for institutional investors to act transparently and responsibly. The code fosters a collaborative approach to corporate governance, enhancing trust among stakeholders.', 'Netherlands', 'climate', 'in_force', '2008-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_2', ARRAY['other sustainability policy', 'netherlands', 'regulations', 'mandatory', 'sdg16', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
