INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7456fcc8-dbc7-50d0-b596-85a7a28b0870', 'Netherlands Environmental Management Act', 'Environmental Management Act', 'This text is based on the text of the Environmental Management Act as published in the Bulletin of Acts and Decrees 2002, no. 239, and later amended.', 'This text is based on the text of the Environmental Management Act as published in the Bulletin of Acts and Decrees 2002, no. 239, and later amended.', 'This text is based on the text of the Environmental Management Act as published in the Bulletin of Acts and Decrees 2002, no. 239, and later amended.', 'Netherlands', 'governance', 'in_force', '2004-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_22', ARRAY['other sustainability policy', 'netherlands', 'regulations', 'sdg11', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ca9eb77d-14a4-51c7-8ae9-808434618567', 'Netherlands Government Governance; Corporate governance in the public sector', 'Government Governance; Corporate governance in the public sector, why and how?', 'This paper provides a framework for analysing policy areas in terms of governance. Evaluating solutions for certain areas using this analysis framework ensures that these solutions are not only a solution for the particular area, but also represent an improvement from the wider governance perspective.', 'This paper provides a framework for analysing policy areas in terms of governance. Evaluating solutions for certain areas using this analysis framework ensures that these solutions are not only a solution for the particular area, but also represent an improvement from the wider governance perspective.', 'This paper provides a framework for analysing policy areas in terms of governance. Evaluating solutions for certain areas using this analysis framework ensures that these solutions are not only a solution for the particular area, but also represent an improvement from the wider governance perspective.', 'Netherlands', 'nature', 'in_force', '2000-01-01'::date, 'Netherlands', 'https://www.carrotsandsticks.org/policies/128_17', ARRAY['other sustainability policy', 'netherlands', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d1778e8f-7329-52e0-adf8-18e083660258', 'Aotearoa New Zealand Climate Standard 1: Climate-related Disclosures', 'Aotearoa New Zealand Climate Standard 1: Climate-related Disclosures (NZ CS 1)', 'In providing a consistent framework for entities to consider the climate-related risks and climate-related opportunities that climate change presents for their activities over the short, medium and long term, the objective of this Standard is to enable primary users to assess the merits of how entities are considering those risks and opportunities, and then make decisions based on these assessments.  The ultimate aim of Aotearoa New Zealand Climate Standards is to support the allocation of capital towards activities that are consistent with a transition to a low-emissions, climate- resilient future. This Standard applies to entities that are required by the Financial Markets Conduct Act 2013 to prepare climate statements or group climate statements that comply with the climate-related disclosure framework. Any entity that elects to or is otherwise directed to prepare climate statements or group climate statements is encouraged to apply all the requirements of Aotearoa New Zealand Climate Standards.1', 'In providing a consistent framework for entities to consider the climate-related risks and climate-related opportunities that climate change presents for their activities over the short, medium and long term, the objective of this Standard is to enable primary users to assess the merits of how entities are considering those risks and opportunities, and then make decisions based on these assessments.  The ultimate aim of Aotearoa New Zealand Climate Standards is to support the allocation of capital towards activities that are consistent with a transition to a low-emissions, climate- resilient future. This Standard applies to entities that are required by the Financial Markets Conduct Act 2013 to prepare climate statements or group climate statements that comply with the climate-related disclosure framework. Any entity that elects to or is otherwise directed to prepare climate statements or group climate statements is encouraged to apply all the requirements of Aotearoa New Zealand Climate Standards.1', 'In providing a consistent framework for entities to consider the climate-related risks and climate-related opportunities that climate change presents for their activities over the short, medium and long term, the objective of this Standard is to enable primary users to assess the merits of how entities are considering those risks and opportunities, and then make decisions based on these assessments.  The ultimate aim of Aotearoa New Zealand Climate Standards is to support the allocation of capital towards activities that are consistent with a transition to a low-emissions, climate- resilient future. This Standard applies to entities that are required by the Financial Markets Conduct Act 2013 to prepare climate statements or group climate statements that comply with the climate-related disclosure framework. Any entity that elects to or is otherwise directed to prepare climate statements or group climate statements is encouraged to apply all the requirements of Aotearoa New Zealand Climate Standards.1', 'New Zealand', 'climate', 'in_force', '2022-01-01'::date, 'New Zealand', 'https://www.carrotsandsticks.org/policies/130_22', ARRAY['sdg13', 'voluntary', 'new zealand', 'disclosure', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('09f2d737-e083-50b4-8139-f0c7e8fdcf2d', 'Aotearoa New Zealand Climate Standard 2: Adoption', 'Aotearoa New Zealand Climate Standard 2: Adoption of Climate-related Disclosures (NZ CS 2)', 'The Aotearoa New Zealand Climate Standard 2 (NZ CS 2) outlines the adoption of climate-related disclosures by entities. The objective of this standard is to ensure that entities disclose relevant and decision-useful climate-related information that supports the transition to a low-emissions, climate-resilient future. Entities are required to adopt the recommendations of the Task Force on Climate-related Financial Disclosures (TCFD) and report on their governance, strategy, risk management, and metrics and targets related to climate change. The standard provides guidance on how to implement the TCFD recommendations, including the need for board-level oversight and engagement, scenario analysis, and disclosure of both quantitative and qualitative information. Entities are also required to disclose their approach to managing and mitigating climate-related risks and opportunities, including any material impacts on their business activities. They should consider their exposure to physical, transition, and liability risks related to climate change and disclose their strategies for managing these risks. The standard applies to entities required to prepare climate statements or group climate statements under the Financial Markets Conduct Act 2013. Entities are encouraged to apply all the requirements of the Aotearoa New Zealand Climate Standards to ensure comprehensive and consistent reporting.', 'The Aotearoa New Zealand Climate Standard 2 (NZ CS 2) outlines the adoption of climate-related disclosures by entities. The objective of this standard is to ensure that entities disclose relevant and decision-useful climate-related information that supports the transition to a low-emissions, climate-resilient future. Entities are required to adopt the recommendations of the Task Force on Climate-related Financial Disclosures (TCFD) and report on their governance, strategy, risk management, and metrics and targets related to climate change. The standard provides guidance on how to implement the TCFD recommendations, including the need for board-level oversight and engagement, scenario analysis, and disclosure of both quantitative and qualitative information. Entities are also required to disclose their approach to managing and mitigating climate-related risks and opportunities, including any material impacts on their business activities. They should consider their exposure to physical, transition, and liability risks related to climate change and disclose their strategies for managing these risks. The standard applies to entities required to prepare climate statements or group climate statements under the Financial Markets Conduct Act 2013. Entities are encouraged to apply all the requirements of the Aotearoa New Zealand Climate Standards to ensure comprehensive and consistent reporting.', 'The Aotearoa New Zealand Climate Standard 2 (NZ CS 2) outlines the adoption of climate-related disclosures by entities. The objective of this standard is to ensure that entities disclose relevant and decision-useful climate-related information that supports the transition to a low-emissions, climate-resilient future. Entities are required to adopt the recommendations of the Task Force on Climate-related Financial Disclosures (TCFD) and report on their governance, strategy, risk management, and metrics and targets related to climate change. The standard provides guidance on how to implement the TCFD recommendations, including the need for board-level oversight and engagement, scenario analysis, and disclosure of both quantitative and qualitative information. Entities are also required to disclose their approach to managing and mitigating climate-related risks and opportunities, including any material impacts on their business activities. They should consider their exposure to physical, transition, and liability risks related to climate change and disclose their strategies for managing these risks. The standard applies to entities required to prepare climate statements or group climate statements under the Financial Markets Conduct Act 2013. Entities are encouraged to apply all the requirements of the Aotearoa New Zealand Climate Standards to ensure comprehensive and consistent reporting.', 'New Zealand', 'climate', 'in_force', '2022-01-01'::date, 'New Zealand', 'https://www.carrotsandsticks.org/policies/130_23', ARRAY['sdg13', 'voluntary', 'sdg16', 'new zealand', 'disclosure', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('87af3428-9c77-53ee-81fd-f9b8bee05107', 'Aotearoa New Zealand Climate Standard 3: NZ CS', 'Aotearoa New Zealand Climate Standard 3: NZ CS 3 General Requirements for Climate-related Disclosures', 'Aotearoa New Zealand Climate Standard 3 (NZ CS 3) provides general requirements for climate-related disclosures by entities. The objective of this standard is to ensure that climate-related information is disclosed in a clear, concise, and decision-useful manner, supporting the transition to a low-emissions, climate-resilient future. The standard requires entities to provide a climate-related disclosure report that includes information on their governance, strategy, risk management, and metrics and targets related to climate change. Entities must also disclose any material climate-related risks and opportunities that could impact their business activities. The report must include information on the entity''s approach to managing and mitigating climate-related risks and opportunities, including their adaptation and transition strategies. It should also detail how the entity is aligned with the Paris Agreement and the goal of limiting global warming to well below 2 degrees Celsius. NZ CS 3 also requires entities to disclose their greenhouse gas emissions, including Scope 1, 2, and 3 emissions, and provide a breakdown of emissions by source. The standard provides guidance on how to calculate emissions and the use of emission factors. Entities are encouraged to apply all the requirements of the Aotearoa New Zealand Climate Standards to ensure comprehensive and consistent reporting. The standard applies to entities required to prepare climate statements or group climate statements under the Financial Markets Conduct Act 2013.', 'Aotearoa New Zealand Climate Standard 3 (NZ CS 3) provides general requirements for climate-related disclosures by entities. The objective of this standard is to ensure that climate-related information is disclosed in a clear, concise, and decision-useful manner, supporting the transition to a low-emissions, climate-resilient future. The standard requires entities to provide a climate-related disclosure report that includes information on their governance, strategy, risk management, and metrics and targets related to climate change. Entities must also disclose any material climate-related risks and opportunities that could impact their business activities. The report must include information on the entity''s approach to managing and mitigating climate-related risks and opportunities, including their adaptation and transition strategies. It should also detail how the entity is aligned with the Paris Agreement and the goal of limiting global warming to well below 2 degrees Celsius. NZ CS 3 also requires entities to disclose their greenhouse gas emissions, including Scope 1, 2, and 3 emissions, and provide a breakdown of emissions by source. The standard provides guidance on how to calculate emissions and the use of emission factors. Entities are encouraged to apply all the requirements of the Aotearoa New Zealand Climate Standards to ensure comprehensive and consistent reporting. The standard applies to entities required to prepare climate statements or group climate statements under the Financial Markets Conduct Act 2013.', 'Aotearoa New Zealand Climate Standard 3 (NZ CS 3) provides general requirements for climate-related disclosures by entities. The objective of this standard is to ensure that climate-related information is disclosed in a clear, concise, and decision-useful manner, supporting the transition to a low-emissions, climate-resilient future. The standard requires entities to provide a climate-related disclosure report that includes information on their governance, strategy, risk management, and metrics and targets related to climate change. Entities must also disclose any material climate-related risks and opportunities that could impact their business activities. The report must include information on the entity''s approach to managing and mitigating climate-related risks and opportunities, including their adaptation and transition strategies. It should also detail how the entity is aligned with the Paris Agreement and the goal of limiting global warming to well below 2 degrees Celsius. NZ CS 3 also requires entities to disclose their greenhouse gas emissions, including Scope 1, 2, and 3 emissions, and provide a breakdown of emissions by source. The standard provides guidance on how to calculate emissions and the use of emission factors. Entities are encouraged to apply all the requirements of the Aotearoa New Zealand Climate Standards to ensure comprehensive and consistent reporting. The standard applies to entities required to prepare climate statements or group climate statements under the Financial Markets Conduct Act 2013.', 'New Zealand', 'climate', 'in_force', '2022-01-01'::date, 'New Zealand', 'https://www.carrotsandsticks.org/policies/130_24', ARRAY['sdg13', 'voluntary', 'sdg16', 'new zealand', 'disclosure', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('93ce885d-b823-55db-a08a-de019347891c', 'New Zealand Financial Sector (Climate-related Disclosures and Other Matters)', 'Financial Sector (Climate-related Disclosures and Other Matters) Amendment Act', 'The Financial Sector (Climate-related Disclosures and Other Matters) Amendment Act 2021 establishes mandatory climate-related disclosures for financial institutions in New Zealand. The law amends the Financial Markets Conduct Act 2013, the Financial Reporting Act 2013, and the Public Audit Act 2001, requiring certain financial market participants to report on climate-related risks, opportunities, and emissions in accordance with climate standards issued by the External Reporting Board (XRB).

Key provisions include:

Scope of Affected Entities:
Large listed issuers
Registered banks, licensed insurers, credit unions, and building societies with total assets exceeding NZD 1 billion
Large fund managers overseeing over NZD 1 billion in assets
Overseas climate reporting entities operating in New Zealand
Climate-related Disclosure Requirements:
Entities must keep climate-related disclosure (CRD) records and file climate statements annually.
Climate statements must disclose climate risks, governance approaches, and greenhouse gas (GHG) emissions.
Reports must follow XRB climate standards and be lodged with the Registrar.
Assurance Requirements:
Independent third-party assurance (audit) of GHG emissions disclosures is required.
Auditors must follow auditing and assurance standards.
Penalties for Non-Compliance:
Fines up to NZD 500,000 (individuals) or NZD 2.5 million (companies) for knowingly failing to comply.
Civil liability and pecuniary penalties up to NZD 5 million for serious violations.
The Act aligns New Zealand’s financial sector with international climate disclosure standards and ensures investors, regulators, and the public have transparent information on climate risks and sustainability practices.', 'The Financial Sector (Climate-related Disclosures and Other Matters) Amendment Act 2021 establishes mandatory climate-related disclosures for financial institutions in New Zealand. The law amends the Financial Markets Conduct Act 2013, the Financial Reporting Act 2013, and the Public Audit Act 2001, requiring certain financial market participants to report on climate-related risks, opportunities, and emissions in accordance with climate standards issued by the External Reporting Board (XRB).

Key provisions include:

Scope of Affected Entities:
Large listed issuers
