INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d796e24a-5a9c-52c7-98cd-f58a9bb410ce', 'New Zealand Corporate Governance Principles', 'Corporate Governance Principles, 2003', 'While some part of this report provides background comment on the Institute’s process that led to the Securities Commission’s review of corporate governance it also provides general comment on the recent United States reporting failures, including the market and government responses to those failures, and the New Zealand government and non-government factors that make up New Zealand’s corporate governance environment.
11. Part V outlines the Institute’s preferred approach to promoting corporate governance in New Zealand. This option follows closely that outlined by the Institute’s working group on corporate reporting. The working group produced the report “Improving Corporate reporting: A Shared Responsibility” for the Minister of Commerce in May this year.', 'While some part of this report provides background comment on the Institute’s process that led to the Securities Commission’s review of corporate governance it also provides general comment on the recent United States reporting failures, including the market and government responses to those failures, and the New Zealand government and non-government factors that make up New Zealand’s corporate governance environment.
11. Part V outlines the Institute’s preferred approach to promoting corporate governance in New Zealand. This option follows closely that outlined by the Institute’s working group on corporate reporting. The working group produced the report “Improving Corporate reporting: A Shared Responsibility” for the Minister of Commerce in May this year.', 'While some part of this report provides background comment on the Institute’s process that led to the Securities Commission’s review of corporate governance it also provides general comment on the recent United States reporting failures, including the market and government responses to those failures, and the New Zealand government and non-government factors that make up New Zealand’s corporate governance environment.
11. Part V outlines the Institute’s preferred approach to promoting corporate governance in New Zealand. This option follows closely that outlined by the Institute’s working group on corporate reporting. The working group produced the report “Improving Corporate reporting: A Shared Responsibility” for the Minister of Commerce in May this year.', 'New Zealand', 'climate', 'in_force', '2003-01-01'::date, 'New Zealand', 'https://www.carrotsandsticks.org/policies/130_6', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg16', 'new zealand', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
