INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('12a2e61e-8f0a-51d0-9619-d47222668795', 'Nigerian Code of Corporate Governance', 'Nigerian Code of Corporate Governance, 2018', 'The Nigerian Code of Corporate Governance 2018 seeks to institutionalise corporate governance best practices in Nigerian companies. The Code is also to promote public awareness of essential corporate values and ethical practices that will enhance the integrity of the business environment. By institutionalising high corporate governance standards, the Code will rebuild public trust and confidence in the Nigerian economy, thus facilitating increased trade and investment.', 'The Nigerian Code of Corporate Governance 2018 seeks to institutionalise corporate governance best practices in Nigerian companies. The Code is also to promote public awareness of essential corporate values and ethical practices that will enhance the integrity of the business environment. By institutionalising high corporate governance standards, the Code will rebuild public trust and confidence in the Nigerian economy, thus facilitating increased trade and investment.', 'The Nigerian Code of Corporate Governance 2018 seeks to institutionalise corporate governance best practices in Nigerian companies. The Code is also to promote public awareness of essential corporate values and ethical practices that will enhance the integrity of the business environment. By institutionalising high corporate governance standards, the Code will rebuild public trust and confidence in the Nigerian economy, thus facilitating increased trade and investment.', 'Nigeria', 'climate', 'in_force', '2018-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_25', ARRAY['regulations', 'mandatory', 'sdg16', 'nigeria', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('69bd17ef-9e1e-516a-ba3b-79bdf88135ec', 'Nigerian Sustainable Finance Roadmap', 'Nigerian Sustainable Finance Roadmap', 'This report lays out the ways in which Nigeria can unlock the investment needed to move onto a more sustainable growth trajectory that will benefit its people, its environment and the economy. It provides an analysis of sustainable finance opportunities in Nigeria out to 2030, assesses the characteristics of these opportunities, and estimates current sustainable finance flows. Based on expert interviews, it also identifies barriers to scaling sustainable finance in Nigeria and lays out options to address them.', 'This report lays out the ways in which Nigeria can unlock the investment needed to move onto a more sustainable growth trajectory that will benefit its people, its environment and the economy. It provides an analysis of sustainable finance opportunities in Nigeria out to 2030, assesses the characteristics of these opportunities, and estimates current sustainable finance flows. Based on expert interviews, it also identifies barriers to scaling sustainable finance in Nigeria and lays out options to address them.', 'This report lays out the ways in which Nigeria can unlock the investment needed to move onto a more sustainable growth trajectory that will benefit its people, its environment and the economy. It provides an analysis of sustainable finance opportunities in Nigeria out to 2030, assesses the characteristics of these opportunities, and estimates current sustainable finance flows. Based on expert interviews, it also identifies barriers to scaling sustainable finance in Nigeria and lays out options to address them.', 'Nigeria', 'climate', 'in_force', '2018-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_26', ARRAY['sdg13', 'other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'nigeria']::text[]) ON CONFLICT (id) DO NOTHING;
