INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bb3fc369-685d-53df-90b4-af255519c767', 'Nigeria Draft Exposure Draft of the Public Sector Governance', 'Draft Exposure Draft of the Public Sector Governance Code in Nigeria, 2016', 'This is the Draft version of the 2016 Corporate Governance Code which purpose is to entrench corporate governance across all sectors of the Nigerian economy, particularly Public Sector Entities, so as to engender healthier, transparent and very competitive entities.', 'This is the Draft version of the 2016 Corporate Governance Code which purpose is to entrench corporate governance across all sectors of the Nigerian economy, particularly Public Sector Entities, so as to engender healthier, transparent and very competitive entities.', 'This is the Draft version of the 2016 Corporate Governance Code which purpose is to entrench corporate governance across all sectors of the Nigerian economy, particularly Public Sector Entities, so as to engender healthier, transparent and very competitive entities.', 'Nigeria', 'climate', 'in_force', '2016-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_24', ARRAY['mandatory', 'sdg5', 'sdg16', 'mandatory_regulations', 'nigeria', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3793b3f2-e8bf-586f-bb16-142a2c77c168', 'Nigeria National Code of Corporate Governance', 'National Code of Corporate Governance, 2016', 'This Governance Code aims at promoting accountability, adequate disclosure, transparency, integrity and most importantly, minority shareholder and stakeholder protection.', 'This Governance Code aims at promoting accountability, adequate disclosure, transparency, integrity and most importantly, minority shareholder and stakeholder protection.', 'This Governance Code aims at promoting accountability, adequate disclosure, transparency, integrity and most importantly, minority shareholder and stakeholder protection.', 'Nigeria', 'climate', 'in_force', '2016-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_4', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'nigeria', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('65ca0471-34f0-5cce-b9bd-5a97e815fbcc', 'Nigeria Not-for-profit organisations: Governance Code', 'Not-for-profit organisations: Governance Code, 2016', 'This Code, to be referred to as the Not-For-Profit Organisations Governance Code 2016, is the outcome of an additional directive given to the Steering Committee on the National Code of Corporate Governance on 29th November 2013 by the Honourable Minister of Trade and Investment.', 'This Code, to be referred to as the Not-For-Profit Organisations Governance Code 2016, is the outcome of an additional directive given to the Steering Committee on the National Code of Corporate Governance on 29th November 2013 by the Honourable Minister of Trade and Investment.', 'This Code, to be referred to as the Not-For-Profit Organisations Governance Code 2016, is the outcome of an additional directive given to the Steering Committee on the National Code of Corporate Governance on 29th November 2013 by the Honourable Minister of Trade and Investment.', 'Nigeria', 'climate', 'in_force', '2016-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_6', ARRAY['regulations', 'mandatory', 'sdg16', 'nigeria', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7141c3d3-73eb-5f35-b7e9-adb3e0aafe5f', 'Rulebook of the Nigerian Stock Exchange', 'Rulebook of the Nigerian Stock Exchange', 'The Rulebook of The Nigerian Stock Exchange, 2015 (the “Rulebook”) is a compilation of all the Rules, Regulations and Guidelines (“Rules”) of The Exchange in one (1) document. It facilitates quick and easy access to the Rules by Dealing Members, Issuers, investors and all other stakeholders who require them.', 'The Rulebook of The Nigerian Stock Exchange, 2015 (the “Rulebook”) is a compilation of all the Rules, Regulations and Guidelines (“Rules”) of The Exchange in one (1) document. It facilitates quick and easy access to the Rules by Dealing Members, Issuers, investors and all other stakeholders who require them.', 'The Rulebook of The Nigerian Stock Exchange, 2015 (the “Rulebook”) is a compilation of all the Rules, Regulations and Guidelines (“Rules”) of The Exchange in one (1) document. It facilitates quick and easy access to the Rules by Dealing Members, Issuers, investors and all other stakeholders who require them.', 'Nigeria', 'governance', 'in_force', '2015-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_5', ARRAY['mandatory', 'other sustainability policy', 'nigeria', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1994dd91-e51b-5fd5-a58e-5e64594afcbe', 'Nigeria Code of Corporate Governance for Banks and Discount', 'Code of Corporate Governance for Banks and Discount Houses in Nigeria and Guidelines for Whistle Blowing in the Nigerian Banking Industry', 'This revised Code provides clear guidelines on all aspects of governance and is expected to enhance Corporate Governance practices for banks in Nigeria. The provisions of this Code represent the minimum standard which banks shall comply. Banks are however encouraged to aspire to higher standards.', 'This revised Code provides clear guidelines on all aspects of governance and is expected to enhance Corporate Governance practices for banks in Nigeria. The provisions of this Code represent the minimum standard which banks shall comply. Banks are however encouraged to aspire to higher standards.', 'This revised Code provides clear guidelines on all aspects of governance and is expected to enhance Corporate Governance practices for banks in Nigeria. The provisions of this Code represent the minimum standard which banks shall comply. Banks are however encouraged to aspire to higher standards.', 'Nigeria', 'governance', 'in_force', '2014-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_22', ARRAY['guidance_frameworks', 'sdg16', 'nigeria', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('428fcc70-f6fa-545a-9fb1-5092d3ca6283', 'Nigeria Implementation of sustainable banking principles by banks, discount', 'Implementation of sustainable banking principles by banks, discount houses and development finance institutions in Nigeria', 'The purpose of this document is to enhance the adapting institutions'' financial success over the long term while ensuring that they remain environmentally and socially responsible.', 'The purpose of this document is to enhance the adapting institutions'' financial success over the long term while ensuring that they remain environmentally and socially responsible.', 'The purpose of this document is to enhance the adapting institutions'' financial success over the long term while ensuring that they remain environmentally and socially responsible.', 'Nigeria', 'climate', 'in_force', '2012-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_2', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'sdg16', 'sdg12', 'nigeria', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5a4a9ba2-34ea-5edb-bcf2-dcec2b0d9950', 'Nigeria Code of Corporate Governace for Licensed Pension Operators', 'Code of Corporate Governace for Licensed Pension Operators', 'The Code of Corporate Governance essentially aims to set out rules based on best practices to guide PFAs (including CPFAs) and PFCs on the structures and processes to be used towards achieving optimal governance set up.', 'The Code of Corporate Governance essentially aims to set out rules based on best practices to guide PFAs (including CPFAs) and PFCs on the structures and processes to be used towards achieving optimal governance set up.', 'The Code of Corporate Governance essentially aims to set out rules based on best practices to guide PFAs (including CPFAs) and PFCs on the structures and processes to be used towards achieving optimal governance set up.', 'Nigeria', 'governance', 'in_force', '2008-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_21', ARRAY['regulations', 'mandatory', 'sdg16', 'nigeria', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('77ee929d-570e-5012-b00a-1324c585be72', 'Nigeria Code of Corporate Governance for Public Companies', 'Code of Corporate Governance for Public Companies, 2008', 'The purpose of this Code is to review the 2003 Code of Corporate Governance for Public Companies in Nigeria, address its weaknesses and to improve the mechanism for enforceability.', 'The purpose of this Code is to review the 2003 Code of Corporate Governance for Public Companies in Nigeria, address its weaknesses and to improve the mechanism for enforceability.', 'The purpose of this Code is to review the 2003 Code of Corporate Governance for Public Companies in Nigeria, address its weaknesses and to improve the mechanism for enforceability.', 'Nigeria', 'governance', 'in_force', '2008-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_3', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'nigeria']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8ab27708-9563-584d-a206-1d38b8ecd01e', 'Nigerian Minerals and Mining Act', 'Nigerian Minerals and Mining Act 2007', 'The Nigerian Minerals and Mining Act provides the regulations and requirements for those entities involved in exploration, mining or quarrying in Nigeria, activities which require the correct permit for operation. Those with a Reconnaissance Permit, Exploration License or Mining Lease are required by Articles 56, 61 and 70, respectively, to submit information and periodical reports, the detail and contents of which will be prescribed by the relevant Ministry. Additionally, Article 84 requires that those with mining leases or licenses to report the particulars of any incident that leads to death or serious injury to both the local police station and the local office of the Mines Inspectorate Department.', 'The Nigerian Minerals and Mining Act provides the regulations and requirements for those entities involved in exploration, mining or quarrying in Nigeria, activities which require the correct permit for operation. Those with a Reconnaissance Permit, Exploration License or Mining Lease are required by Articles 56, 61 and 70, respectively, to submit information and periodical reports, the detail and contents of which will be prescribed by the relevant Ministry. Additionally, Article 84 requires that those with mining leases or licenses to report the particulars of any incident that leads to death or serious injury to both the local police station and the local office of the Mines Inspectorate Department.', 'The Nigerian Minerals and Mining Act provides the regulations and requirements for those entities involved in exploration, mining or quarrying in Nigeria, activities which require the correct permit for operation. Those with a Reconnaissance Permit, Exploration License or Mining Lease are required by Articles 56, 61 and 70, respectively, to submit information and periodical reports, the detail and contents of which will be prescribed by the relevant Ministry. Additionally, Article 84 requires that those with mining leases or licenses to report the particulars of any incident that leads to death or serious injury to both the local police station and the local office of the Mines Inspectorate Department.', 'Nigeria', 'climate', 'in_force', '2007-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_29', ARRAY['regulations', 'mandatory', 'nigeria', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('34e183e4-ed81-5fef-9c33-d1ad928eb3b0', 'Code of Corporate Governance for Banks in Nigeria', 'Code of Corporate Governance for Banks in Nigeria Post Consolidation', 'The consolidation of the banking industry necessitated a review of the existing code for the Nigerian Banks. This new code therefore was developed to compliment the earlier ones and enhance their effectiveness for the Nigerian banking industry.', 'The consolidation of the banking industry necessitated a review of the existing code for the Nigerian Banks. This new code therefore was developed to compliment the earlier ones and enhance their effectiveness for the Nigerian banking industry.', 'The consolidation of the banking industry necessitated a review of the existing code for the Nigerian Banks. This new code therefore was developed to compliment the earlier ones and enhance their effectiveness for the Nigerian banking industry.', 'Nigeria', 'governance', 'in_force', '2006-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_20', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'nigeria', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6dccb209-2cd6-5cdd-afc6-3fd71e7811f5', 'Code of Corporate Governance in Nigeria', 'Code of Corporate Governance in Nigeria, 2003', 'This document outlines a code to make provisions for the best practices to be followed by public quoted companies and for all other companies with multiple stakeholders registered in Nigeria in the exercise at power over the direction of the enterprise, the supervision of executive actions, the transparency and accountability in governance of these companies within the regulatory framework and market;and for other purposes connected therewith.', 'This document outlines a code to make provisions for the best practices to be followed by public quoted companies and for all other companies with multiple stakeholders registered in Nigeria in the exercise at power over the direction of the enterprise, the supervision of executive actions, the transparency and accountability in governance of these companies within the regulatory framework and market;and for other purposes connected therewith.', 'This document outlines a code to make provisions for the best practices to be followed by public quoted companies and for all other companies with multiple stakeholders registered in Nigeria in the exercise at power over the direction of the enterprise, the supervision of executive actions, the transparency and accountability in governance of these companies within the regulatory framework and market;and for other purposes connected therewith.', 'Nigeria', 'governance', 'in_force', '2003-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_19', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'nigeria']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('00b2d1be-d30e-57c1-8ec9-47a925b8530e', 'Nigeria Nuclear safety and radiation protection act', 'Nuclear safety and radiation protection act', 'This document outlines the nucelar safety and radiation protection Act of 1995.', 'This document outlines the nucelar safety and radiation protection Act of 1995.', 'This document outlines the nucelar safety and radiation protection Act of 1995.', 'Nigeria', 'governance', 'in_force', '1995-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_14', ARRAY['mandatory', 'other sustainability policy', 'nigeria', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('14f11772-a1b0-5b8d-86b9-75fd0661c80d', 'Nigeria: Water Resources Decree', 'Nigeria: Water Resources Decree 1993', 'The right to the use and control of all surface and groundwater and of all water in any water-course affecting more than one State as described in Schedule to this Decree, together with the bed and banks thereof, are by virtue of this Decree and without further assurance vested in the Government of the Federation for the purpose of (a) promoting the optimum planning, development and use of the Nigeria''s water resources; (b) ensuring the co-ordination of such activities as are likely to influence the quality, quantity; distribution, use and management of water;(c) ensuring the application of appropriate standards and techniques for the investigation, use, control, protection, management and administration of water resources; and (d) facilitating technical assistance and rehabilitation for water supplies.', 'The right to the use and control of all surface and groundwater and of all water in any water-course affecting more than one State as described in Schedule to this Decree, together with the bed and banks thereof, are by virtue of this Decree and without further assurance vested in the Government of the Federation for the purpose of (a) promoting the optimum planning, development and use of the Nigeria''s water resources; (b) ensuring the co-ordination of such activities as are likely to influence the quality, quantity; distribution, use and management of water;(c) ensuring the application of appropriate standards and techniques for the investigation, use, control, protection, management and administration of water resources; and (d) facilitating technical assistance and rehabilitation for water supplies.', 'The right to the use and control of all surface and groundwater and of all water in any water-course affecting more than one State as described in Schedule to this Decree, together with the bed and banks thereof, are by virtue of this Decree and without further assurance vested in the Government of the Federation for the purpose of (a) promoting the optimum planning, development and use of the Nigeria''s water resources; (b) ensuring the co-ordination of such activities as are likely to influence the quality, quantity; distribution, use and management of water;(c) ensuring the application of appropriate standards and techniques for the investigation, use, control, protection, management and administration of water resources; and (d) facilitating technical assistance and rehabilitation for water supplies.', 'Nigeria', 'governance', 'in_force', '1993-01-01'::date, 'Nigeria', 'https://www.carrotsandsticks.org/policies/133_16', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'nigeria']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('516f718b-2ad2-586e-a922-4914c473d59a', 'Norway Prop. 130 L (2024–2025) Act on the Prevention', 'Prop. 130 L (2024–2025) Act on the Prevention and Reduction of Food Waste (Food Waste Act)', 'The Prop. 130 L (2024-2025) Act on the Prevention and Reduction of Food Waste in Norway aims to define food waste, require prevention measures, promote donations, and outline enforcement procedures. It targets businesses, organizations, and individuals involved in food production, distribution, and consumption.', 'The Prop. 130 L (2024-2025) Act on the Prevention and Reduction of Food Waste in Norway aims to define food waste, require prevention measures, promote donations, and outline enforcement procedures. It targets businesses, organizations, and individuals involved in food production, distribution, and consumption.', 'The Prop. 130 L (2024-2025) Act on the Prevention and Reduction of Food Waste in Norway aims to define food waste, require prevention measures, promote donations, and outline enforcement procedures. It targets businesses, organizations, and individuals involved in food production, distribution, and consumption.', 'Norway', 'nature', 'in_force', '2025-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_29', ARRAY['norway', 'mandatory', 'sdg12', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9be98497-5a8c-59e0-851b-6c12891a090d', 'Norway Regulations on amendments to transitional rules to the', 'Regulations on amendments to transitional rules to the Act on Amendments to the Accounting Act, etc. (sustainability reporting)', 'The policy document outlines amendments to transitional rules regarding sustainability reporting as per the Accounting Act in Norway. It mandates large public interest companies with over 500 employees to comply with new reporting requirements starting from the fiscal year 2024. Other large companies will follow in 2027, while small and medium-sized listed companies will be required to comply by 2028. The policy aims to enhance transparency in sustainability practices among significant enterprises. It is mandatory for the specified companies.', 'The policy document outlines amendments to transitional rules regarding sustainability reporting as per the Accounting Act in Norway. It mandates large public interest companies with over 500 employees to comply with new reporting requirements starting from the fiscal year 2024. Other large companies will follow in 2027, while small and medium-sized listed companies will be required to comply by 2028. The policy aims to enhance transparency in sustainability practices among significant enterprises. It is mandatory for the specified companies.', 'The policy document outlines amendments to transitional rules regarding sustainability reporting as per the Accounting Act in Norway. It mandates large public interest companies with over 500 employees to comply with new reporting requirements starting from the fiscal year 2024. Other large companies will follow in 2027, while small and medium-sized listed companies will be required to comply by 2028. The policy aims to enhance transparency in sustainability practices among significant enterprises. It is mandatory for the specified companies.', 'Norway', 'climate', 'in_force', '2025-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_33', ARRAY['regulations', 'mandatory', 'sdg16', 'norway', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b18b7a70-c4bd-57ad-8dbd-f1a3b83046bf', 'Norway Prop. 57L (2023–2024) Amendments to the Accounting Act', 'Prop. 57L (2023–2024) Amendments to the Accounting Act, etc. (sustainability reporting)', 'The Prop. 57L (2023–2024) in Norway proposes amendments to the Accounting Act for sustainability reporting. It aims to enhance reporting standards for companies, including requirements for sustainability disclosures, targeting entities of all sizes and sectors.', 'The Prop. 57L (2023–2024) in Norway proposes amendments to the Accounting Act for sustainability reporting. It aims to enhance reporting standards for companies, including requirements for sustainability disclosures, targeting entities of all sizes and sectors.', 'The Prop. 57L (2023–2024) in Norway proposes amendments to the Accounting Act for sustainability reporting. It aims to enhance reporting standards for companies, including requirements for sustainability disclosures, targeting entities of all sizes and sectors.', 'Norway', 'climate', 'in_force', '2024-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_28', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'norway']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('da0fd13b-0f88-5344-ab67-26cb6fc3f111', 'Norway supplementary tax on under-taxed income in groups (the', 'Act on supplementary tax on under-taxed income in groups (the Supplementary Tax Act)', 'The Supplementary Tax Act in Norway, effective 2024, aims to levy additional tax on under-taxed income in corporate groups with an effective tax rate below 15%. It applies to corporate entities with annual group income of at least 750 million euros, excluding specified entities, and allows for supplementary tax calculations and exemptions based on ownership structures.', 'The Supplementary Tax Act in Norway, effective 2024, aims to levy additional tax on under-taxed income in corporate groups with an effective tax rate below 15%. It applies to corporate entities with annual group income of at least 750 million euros, excluding specified entities, and allows for supplementary tax calculations and exemptions based on ownership structures.', 'The Supplementary Tax Act in Norway, effective 2024, aims to levy additional tax on under-taxed income in corporate groups with an effective tax rate below 15%. It applies to corporate entities with annual group income of at least 750 million euros, excluding specified entities, and allows for supplementary tax calculations and exemptions based on ownership structures.', 'Norway', 'governance', 'in_force', '2024-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_30', ARRAY['mandatory', 'norway', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b4168f58-f2e8-5561-ae30-9fb958d131fa', 'Norway Amendment Act to the Supplementary Tax Act', 'Amendment Act to the Supplementary Tax Act', 'The Amendment Act to the Supplementary Tax Act in Norway, effective 2024, outlines changes to underreported income tax within corporate groups. It specifies exemptions, adjusted financial reporting, and tax distribution rules for entities within the group. This policy targets financial entities in Norway subject to supplementary tax regulations.', 'The Amendment Act to the Supplementary Tax Act in Norway, effective 2024, outlines changes to underreported income tax within corporate groups. It specifies exemptions, adjusted financial reporting, and tax distribution rules for entities within the group. This policy targets financial entities in Norway subject to supplementary tax regulations.', 'The Amendment Act to the Supplementary Tax Act in Norway, effective 2024, outlines changes to underreported income tax within corporate groups. It specifies exemptions, adjusted financial reporting, and tax distribution rules for entities within the group. This policy targets financial entities in Norway subject to supplementary tax regulations.', 'Norway', 'climate', 'in_force', '2024-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_31', ARRAY['mandatory', 'norway', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('23de77a6-88c2-59f5-a4dc-a1e8a86c004e', 'Norway Legislative Decree 80', 'Legislative Decree 80(2023–2024)', 'Legislative Decree 80 (2023-2024) in Norway mandates sustainability reporting for certain accounting entities. It applies to public limited companies, banks, insurance companies, and state enterprises, among others, while excluding alternative investment funds. The decree outlines requirements for annual reports, including financial and non-financial indicators related to environmental, social, and governance (ESG) factors. The aim is to enhance transparency and accountability in sustainability practices. This policy is mandatory for the specified entities and sets clear thresholds for categorizing companies based on size and reporting obligations.', 'Legislative Decree 80 (2023-2024) in Norway mandates sustainability reporting for certain accounting entities. It applies to public limited companies, banks, insurance companies, and state enterprises, among others, while excluding alternative investment funds. The decree outlines requirements for annual reports, including financial and non-financial indicators related to environmental, social, and governance (ESG) factors. The aim is to enhance transparency and accountability in sustainability practices. This policy is mandatory for the specified entities and sets clear thresholds for categorizing companies based on size and reporting obligations.', 'Legislative Decree 80 (2023-2024) in Norway mandates sustainability reporting for certain accounting entities. It applies to public limited companies, banks, insurance companies, and state enterprises, among others, while excluding alternative investment funds. The decree outlines requirements for annual reports, including financial and non-financial indicators related to environmental, social, and governance (ESG) factors. The aim is to enhance transparency and accountability in sustainability practices. This policy is mandatory for the specified entities and sets clear thresholds for categorizing companies based on size and reporting obligations.', 'Norway', 'climate', 'in_force', '2024-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_32', ARRAY['regulations', 'mandatory', 'sdg16', 'norway', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('391019f0-cf20-51d0-bbc5-7ae7ddf2f968', 'Norway amendments to the Securities Trading Act and the', 'Act on amendments to the Securities Trading Act and the Accounting Act, etc. (periodic reporting and implementation of directives)', 'This document is an act on amendments to the Securities Trading Act and the Accounting Act, etc.', 'This document is an act on amendments to the Securities Trading Act and the Accounting Act, etc.', 'This document is an act on amendments to the Securities Trading Act and the Accounting Act, etc.', 'Norway', 'climate', 'in_force', '2021-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_22', ARRAY['mandatory', 'other sustainability policy', 'norway', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
